'use strict';
const ASSET='../../apps/miniprogram/src/assets/';
const pts=[{id:'north',name:'北城邻里自提点',address:'北城路 18 号 · 便民服务站',paid:12,stock:60,arrival:'9月30日 16:00–18:00'},{id:'south',name:'南苑社区自提点',address:'南苑小区东门 · 邻里驿站',paid:26,stock:40,arrival:'9月30日 17:00–19:00'},{id:'west',name:'西街便民自提点',address:'西街 26 号 · 社区服务中心',paid:4,stock:20,arrival:'10月1日 09:00–11:00'}];
const initial={mode:'point',threshold:20,title:'乡味米粉 · 第08期',selected:['north','south','west'],published:false,point:'north',orderFilter:'全部',more:false,orderState:'待付款',reconciled:false};
let saved;try{saved=JSON.parse(sessionStorage.getItem('xwj-prototype-v2')||'null')}catch{}
const s={...initial,...saved};let modal=null,timer,route='';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'¥'+Number(n).toFixed(2);
const badge=(txt,tone='')=>`<span class="tag ${tone}">${txt}</span>`;
function persist(){sessionStorage.setItem('xwj-prototype-v2',JSON.stringify(s))}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(timer);timer=setTimeout(()=>el.classList.remove('show'),2600)}
function go(p){if(location.hash==='#'+p)render();else location.hash=p}
const current=()=>pts.find(p=>p.id===s.point)||pts[0];
const selected=()=>pts.filter(p=>s.selected.includes(p.id));
const total=()=>selected().reduce((n,p)=>n+p.paid,0);
const progress=p=>s.mode==='point'?p.paid:total();
const ready=p=>progress(p)>=s.threshold;
const stateText=p=>ready(p)?'已达成团条件':'收单中';
const modeText=()=>s.mode==='point'?'各自提点独立成团':'所有自提点合计成团';
const photo=(file,alt,cls='')=>`<img class="${cls}" src="${ASSET+file}" alt="${alt}">`;
function toolbar(){const type=route.startsWith('/mini')?'mini':route==='/review'?'review':'admin';return `<header class="reviewbar"><div class="reviewbrand"><span class="mark">乡</span>活动与履约 · 交互提案</div><nav class="reviewtabs" aria-label="原型视角"><a class="${type==='admin'?'active':''}" href="#/admin/activities">运营后台</a><a class="${type==='mini'?'active':''}" href="#/mini/home">小程序</a><a class="${type==='review'?'active':''}" href="#/review">方案确认</a></nav><span class="reviewbadge">设计预览 · 全部为示例数据</span></header>`}
function head(k,t,d,extra=''){return `<div class="pagehead"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div>${extra}</div>`}
function adminShell(body){let nav=[['activities','▦','活动与团期'],['orders','▤','订单管理'],['finance','◈','财务对账']];return `<div class="shell"><aside class="sidebar"><div class="row brand"><span class="mark">乡</span><div><strong>乡味集</strong><small>社区团购 · 运营管理</small></div></div><div><div class="navtitle">业务工作台</div><nav class="sidenav">${nav.map(([id,i,t])=>`<a class="${route.includes(id)||id==='activities'&&route.includes('/new')?'active':''}" href="#/admin/${id}"><span>${i}</span>${t}</a>`).join('')}</nav></div><div class="sidebottom"><b>运营管理员</b><small style="display:block;margin-top:5px">示例工作台</small></div></aside><main class="main"><div class="breadcrumb">工作台 &nbsp; / &nbsp; ${route.includes('finance')?'财务对账':route.includes('orders')?'订单管理':'活动与团期'}</div>${body}</main></div>`}
function activities(){return head('CAMPAIGN OPERATIONS','一次配置，各点有序开团','统一商品与活动安排，按自提点查看成团进度和领取时间。',`<button class="primary" data-act="edit">配置多点位活动</button>`)+`<section class="stats"><div class="stat"><label>进行中活动</label><b>2</b><small>各点进度独立可见</small></div><div class="stat"><label>本活动覆盖点位</label><b>${selected().length}<small> 个</small></b><small>支持同一活动选择多个点位</small></div><div class="stat"><label>本活动已支付</label><b>${total()}<small> 件</small></b><small>成团按件数计算</small></div><div class="stat"><label>${s.mode==='point'?'已达标点位':'全活动进度'}</label><b>${s.mode==='point'?selected().filter(ready).length+'/'+selected().length:total()+'/'+s.threshold}</b><small>达到门槛后继续售卖至截单</small></div></section><section class="panel"><header class="panelhead"><div class="activitybanner">${photo('product-rice-noodles.jpg','手作米粉')}<div><h2>${esc(s.title)}</h2><div class="row wrap">${badge(s.published?'已模拟发布':'收单中')}${badge(modeText(),'gray')}<small>9月29日 20:00 截单</small></div></div></div><button data-act="edit">配置活动</button></header><div class="tablewrap"><table><thead><tr><th>自提点</th><th>成团进度</th><th>库存分配</th><th>预计领取时间</th><th>状态</th><th>操作</th></tr></thead><tbody>${selected().map(p=>`<tr><td><strong>${p.name}</strong><small>${p.address}</small></td><td>${s.mode==='point'?p.paid:total()} / ${s.threshold} 件<small>${s.mode==='point'?'本点已支付':'全活动合计 · 本点 '+p.paid+' 件'}</small><div class="progress"><i style="width:${Math.min(100,progress(p)/s.threshold*100)}%"></i></div></td><td>${p.stock} 件<small>剩余 ${p.stock-p.paid} 件</small></td><td>${p.arrival}</td><td>${badge(stateText(p),ready(p)?'':'amber')}</td><td><button class="quiet" data-act="preview" data-id="${p.id}">查看小程序 →</button></td></tr>`).join('')}</tbody></table></div><div class="panelbody"><div class="notice green" style="margin:0">${s.mode==='point'?'各点独立判断是否达标，未达标点位的处理不影响其他点位。':'所有已选点位的已支付件数共同计入门槛；达标后各点分别配送和履约。'} 截单前仍可继续购买，售罄即停止。</div></div></section><section class="panel"><div class="panelhead"><div><h3>同点另一团期 · 手作豆皮专场</h3><p>北城邻里自提点 · 8 / 5 件 · 9月30日 20:00 截单 · 10月1日到货</p></div>${badge('已达成团条件')}</div></section><p class="bottomnote">提案：活动统一管理，每个自提点保留独立库存和履约安排。成团口径可在配置页切换对照，尚未成为正式业务规则。</p>`}
function form(){return head('CREATE CAMPAIGN','配置多点位活动','先统一商品，再确认各点库存、成团口径和领取安排。',`<button data-act="cancel-edit">返回活动</button>`)+`<div class="notice">方案待确认：可切换两种成团口径，保存后在小程序预览中比较消费者看到的信息。示例库存按点分配。</div><form id="campaign-form"><div class="formgrid"><div><section class="panel"><div class="panelhead"><h2>01 &nbsp; 活动与商品</h2></div><div class="panelbody"><label class="field">活动名称<input name="title" required maxlength="35" value="${esc(s.title)}"></label><div class="formcols"><label class="field">截单时间<input readonly aria-label="示例截单时间" value="2026-09-29 20:00"></label><label class="field">商品<input readonly aria-label="示例商品" value="乡味手作米粉 · 500g"></label></div><div class="row">${photo('product-rice-noodles.jpg','米粉','')}<div><h3>乡味手作米粉</h3><p class="tiny muted">统一售价 ¥12.80 / 份 · 库存按点分配</p></div></div></div></section><section class="panel"><div class="panelhead"><h2>02 &nbsp; 参与自提点</h2><small>可多选</small></div><div class="panelbody">${pts.map(p=>`<label class="pointcheck"><input type="checkbox" name="points" value="${p.id}" ${s.selected.includes(p.id)?'checked':''}><span><b>${p.name}</b><small>分配 ${p.stock} 件 · ${p.arrival} 到货</small></span></label>`).join('')}</div></section></div><div><section class="panel"><div class="panelhead"><h2>03 &nbsp; 成团规则</h2>${badge('待确认','amber')}</div><div class="panelbody"><label class="choice"><input type="radio" name="mode" value="point" ${s.mode==='point'?'checked':''}>各自提点独立成团<small>每个点分别达到门槛；适合各点独立核算配送成本。</small></label><label class="choice"><input type="radio" name="mode" value="all" ${s.mode==='all'?'checked':''}>所有自提点合计成团<small>各点已支付件数合计；适合集中采购、统一备货。</small></label><label class="field" style="margin-top:22px">最低成团件数<input name="threshold" type="number" min="1" max="1000" required value="${s.threshold}"><small>按商品件数计算，一个用户买多件会累计。</small></label><div class="formsummary"><b>达到门槛后的处理</b><br>继续售卖，到截单或库存售罄时停止。<br><br><b>未达到门槛</b><br>本提案示例采用取消并原路退款。<br><small>顺延规则可在正式实现时沿用已确认约定。</small></div></div></section><div class="formfooter"><button type="button" data-act="cancel-edit">取消</button><button type="submit" class="primary">保存并预览活动</button></div></div></div></form>`}
function orders(){return head('ORDER WORKSPACE','订单管理','按活动与自提点定位订单，保留可返回的列表入口。')+`<div class="filters"><input class="filterinput" id="order-query" placeholder="搜索示例订单号" aria-label="搜索订单号"><button data-act="search-order">查询</button><button data-act="reset-order">重置</button></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>订单号 / 商品</th><th>活动 / 自提点</th><th>订单金额</th><th>支付状态</th><th>操作</th></tr></thead><tbody id="order-rows"><tr><td><strong>XW-DEMO-0028</strong><small>乡味手作米粉 × 2</small></td><td>乡味米粉 · 第08期<small>北城邻里自提点</small></td><td>¥25.60</td><td>${badge(s.orderState,s.orderState==='待付款'?'amber':'gray')}</td><td><a class="quiet" href="#/admin/orders/DEMO-0028">查看详情 →</a></td></tr><tr><td><strong>XW-DEMO-0021</strong><small>乡味手作豆皮 × 1</small></td><td>手作豆皮专场<small>南苑社区自提点</small></td><td>¥9.90</td><td>${badge('已支付')}</td><td><button class="quiet" data-act="history">查看历史订单 →</button></td></tr></tbody></table></div></div><p class="bottomnote">此原型使用页面地址导航。进入订单详情后可用浏览器后退返回，刷新仍停留在当前页面。</p>`}
function orderDetail(){return head('ORDER DETAIL','订单 XW-DEMO-0028','乡味米粉 · 第08期 / 北城邻里自提点',`<a href="#/admin/orders"><button>← 返回订单列表</button></a>`)+`<div class="panel"><div class="panelhead"><h2>支付与订单状态</h2>${badge(s.orderState,s.orderState==='待付款'?'amber':'gray')}</div><div class="panelbody"><div class="detailgrid"><div><label>应付金额</label><b class="amount">¥25.60</b></div><div><label>商品</label>乡味手作米粉 500g × 2</div><div><label>订单有效期</label>2026-09-28 18:15 前完成支付</div><div><label>领取地点</label>北城路 18 号 · 便民服务站</div></div><div class="ordersteps"><div><b>1 · 订单已创建</b><small>等待消费者完成支付</small></div><div><b>2 · ${s.orderState==='已关闭'?'支付单已关闭':'支付渠道待确认'}</b><small>${s.orderState==='已关闭'?'原支付入口不再受理付款':'以实际收款结果更新状态'}</small></div><div><b>3 · ${s.orderState==='已关闭'?'订单已取消':'付款后进入团期'}</b><small>${s.orderState==='已关闭'?'库存已释放，可重新选购':'达标后于截单时进入履约'}</small></div></div>${s.orderState==='已关闭'?'<div class="notice green">此订单已关闭且未收款。若支付结果仍未知，界面应保持“核对中”，不提前显示关闭成功。</div>':'<div class="notice">取消时先核对收款状态。若已收款，应进入退款处理；不能直接把已付款订单标为关闭。</div>'}<button class="primary" data-act="close-order" ${s.orderState!=='待付款'?'disabled':''}>${s.orderState==='已关闭'?'订单已关闭':s.orderState==='核对中'?'正在核对支付状态…':'取消未付款订单'}</button></div></div><p class="bottomnote">交互示例演示“未收款 → 关闭支付单 → 取消订单”。所有动作只改变本页示例状态。</p>`}
function finance(){return head('FINANCE RECONCILIATION','每天的收款，都有据可核','示例展示账单核对与差异处理；对账方式由正式方案另行确认。',`<button data-act="bill-info">查看账单来源</button>`)+`<div class="stats"><div class="stat"><label>核对日期</label><b style="font-size:23px">09月27日</b><small>示例账单</small></div><div class="stat"><label>平台净收款</label><b>¥1,280</b><small>收款减退款</small></div><div class="stat"><label>微信账单净额</label><b>¥1,270</b><small>收款减退款 · 不含手续费</small></div><div class="stat"><label>待处理差异</label><b>${s.reconciled?'0':'1'}<small> 笔</small></b><small>${s.reconciled?'已记录人工核查结果':'差异金额 ¥10.00'}</small></div></div><div class="panel"><div class="panelhead"><h2>差异记录</h2>${badge(s.reconciled?'已处理':'待核查',s.reconciled?'':'amber')}</div><div class="tablewrap"><table><thead><tr><th>订单号</th><th>差异类型</th><th>平台退款</th><th>账单退款</th><th>处理</th></tr></thead><tbody><tr><td><strong>XW-DEMO-0016</strong><small>手作豆皮专场 · 北城邻里自提点</small></td><td>退款记录待同步</td><td>¥0.00</td><td>¥10.00</td><td><button class="quiet" data-act="reconcile">${s.reconciled?'查看处理记录':'查看并处理 →'}</button></td></tr></tbody></table></div></div><div class="notice green">核对结果与业务账务分开记录。标记已处理不会直接修改订单金额，也不会发起扣款或退款。</div>`}
function miniHeader(title,back=''){return `<div class="statusbar"><span>9:41</span><span>▂▄▆ &nbsp; ▰</span></div><div class="mininav">${back?`<button class="back" data-go="${back}" aria-label="返回">‹</button>`:''}${title}<span class="capsule">••• &nbsp; ◉</span></div>`}
function tabs(active){return `<nav class="minitab">${[['home','首页','tab-home'],['orders','订单','tab-orders']].map(([p,t,i])=>`<a href="#/mini/${p}" class="${active===p?'active':''}">${photo(i+'-'+(active===p?'active':'default')+'.png','')}<span>${t}</span></a>`).join('')}</nav>`}
function miniShell(body){const section=route.split('/')[2];const notes={home:'按团期区分截单与到货时间，同一个点同时开多个团也不会混在一个倒计时里。',detail:'成团口径来自后台活动配置。“已达条件”与“正式截单成团”分别表达。',orders:'历史商品保留购买时的图文。列表提供分类与分批加载，不依赖当前在售团期。',points:'点位展示各自售卖情况；切换后只展示该点可购买的团期。'};return `<main class="mobilelayout"><aside class="brief"><div class="eyebrow">MINI PROGRAM / PREVIEW</div><h1>每一团的安排，<br><em>都看得明白。</em></h1><p>延续原有暖色小程序布局，把点位、团期和领取时间放到用户真正需要它们的位置。</p><nav class="briefnav">${[['home','01','分团期首页'],['detail','02','成团详情'],['orders','03','历史订单'],['points','04','切换自提点']].map(([p,n,t])=>`<a class="${section===p?'active':''}" href="#/mini/${p}"><b>${n}</b>${t}</a>`).join('')}</nav><div class="briefnote">${notes[section]||notes.home}<br><br>当前配置：${modeText()} · ${s.threshold} 件<br><a class="quiet" href="#/admin/new">去后台调整方案 →</a></div></aside><div><section class="phone" aria-label="小程序交互预览"><div class="phonebody">${body}</div></section><p class="samplelabel">可点击点位、商品、订单及底部导航 · 全部为示例</p></div></main>`}
function product(file,title,price,detail=true){return `<div class="product">${photo(file,title)}<div><h3>${title}</h3><small>${file.includes('rice')?'500g / 份 · 手工制作':'250g / 份 · 当日制作'}</small><div class="product-bottom"><span class="price">${money(price)}</span><button class="primary" ${detail?'data-go="/mini/detail"':'data-act="tofu"'}>选购 →</button></div></div></div>`}
function miniHome(){const p=current(),available=s.selected.includes(p.id);return miniHeader('乡味集')+`<div class="miniscroll"><button class="miniswitch" data-go="/mini/points"><span><small>当前自提点</small><strong>⌖ ${p.name}</strong></span><span>切换 ›</span></button><div class="miniheading"><h2>本点正在开团</h2><small>${(available?1:0)+(p.id==='north'?1:0)} 个团期</small></div>${available?`<section class="mini-group"><header class="mini-group-head"><div class="row between"><h3>${esc(s.title)}</h3>${badge(stateText(p),ready(p)?'':'amber')}</div><div class="schedule"><span>9月29日 20:00 截单</span><span>${p.arrival.split(' ')[0]} 领取</span></div></header>${product('product-rice-noodles.jpg','乡味手作米粉',12.8)}<footer class="groupfoot"><span>${s.mode==='all'?'全活动':'本点'}已支付 ${progress(p)} / ${s.threshold} 件</span><a href="#/mini/detail">查看成团规则 ›</a></footer></section>`:''}${p.id==='north'?`<section class="mini-group"><header class="mini-group-head"><div class="row between"><h3>手作豆皮专场</h3>${badge('已达成团条件')}</div><div class="schedule"><span>9月30日 20:00 截单</span><span>10月1日 领取</span></div></header>${product('product-tofu-strips.jpg','农家手作豆皮',9.9,false)}<footer class="groupfoot"><span>本点已支付 8 / 5 件</span><span>截单前可继续购买</span></footer></section>`:''}${!available&&p.id!=='north'?'<div class="empty-state">本点暂无可购买团期<br><br><button data-go="/mini/points">看看其他自提点</button></div>':''}<p class="samplelabel">每个团期独立截单，请分别留意领取时间</p></div>${tabs('home')}`}
function miniDetail(){const p=current();if(!s.selected.includes(p.id))return miniHeader('商品与团期','/mini/home')+`<div class="miniscroll"><section class="minicard"><h2>本自提点暂不参与这个活动</h2><p>请选择参与活动的自提点，查看对应的成团进度与领取安排。</p><button class="primary" data-go="/mini/points">选择自提点</button></section></div>`;return miniHeader('商品与团期','/mini/home')+`<div class="miniscroll">${photo('product-rice-noodles.jpg','乡味手作米粉','heroimg')}<div class="row between" style="margin:15px 2px 8px"><span class="price">¥12.80 <small>/ 500g</small></span><small>本点已支付 ${p.paid} 件</small></div><h2>乡味手作米粉</h2><p class="tiny muted" style="margin-top:6px">${esc(s.title)} · ${p.name}</p><section class="minicard"><div class="row between"><h3>本团成团进度</h3>${badge(stateText(p),ready(p)?'':'amber')}</div><p>${s.mode==='point'?'本自提点独立成团':'所有参与自提点合计成团'} · 按已支付件数计算</p><div class="mini-progress"><i style="width:${Math.min(100,progress(p)/s.threshold*100)}%"></i></div><div class="row between"><b style="font-size:13px">已支付 ${progress(p)} / ${s.threshold} 件</b><small>${ready(p)?'已达最低件数':'还差 '+(s.threshold-progress(p))+' 件'}</small></div><p style="margin-top:13px;color:#a67a55">达到最低件数后仍可购买，截单时正式判定成团。库存售罄会提前停止购买。</p></section><section class="minicard"><h3>这份商品，何时去取？</h3><div class="facts"><div><span>截单</span><b>9月29日 20:00</b></div><div><span>预计到货</span><b>${p.arrival}</b></div><div><span>领取地点</span><b>${p.name}</b></div></div><p style="margin-top:15px">具体可领取状态以到货通知为准。若截单未成团，本示例方案取消并原路退款。</p></section></div><div class="minipay"><span class="price">¥12.80</span><button class="primary" data-act="buy">确认领取安排</button></div>`}
function miniOrders(){let rows=[{id:'XW-DEMO-0021',name:'农家手作豆皮',img:'product-tofu-strips.jpg',status:'待提货',price:9.9,date:'9月27日',note:'北城邻里自提点 · 到货后3日内领取'},{id:'XW-DEMO-0012',name:'乡味手作米粉',img:'product-rice-noodles.jpg',status:'已完成',price:25.6,date:'9月20日',note:'第07期 · 商品已结束售卖'},{id:'XW-DEMO-0008',name:'农家手作豆皮',img:'product-tofu-strips.jpg',status:'已完成',price:19.8,date:'9月16日',note:'第06期 · 已领取'}];if(!s.more)rows=rows.slice(0,2);if(s.orderFilter!=='全部')rows=rows.filter(x=>x.status===s.orderFilter);return miniHeader('我的订单')+`<div class="miniscroll"><div class="mini-chips">${['全部','待提货','已完成'].map(f=>`<button class="${s.orderFilter===f?'active':''}" data-act="filter" data-id="${f}">${f}</button>`).join('')}</div>${rows.map(x=>`<article class="miniorder"><header><span>${x.id}</span><b style="color:var(--green)">${x.status}</b></header><div class="product">${photo(x.img,x.name)}<div><h3>${x.name}</h3><small>${x.note}</small><div style="margin-top:8px;font-size:13px">实付 ${money(x.price)}</div></div></div><footer><span>${x.date} 下单</span><button class="quiet" data-id="${x.id}" data-act="${x.status==='待提货'?'pickup':'snapshot'}">${x.status==='待提货'?'查看提货安排':'查看购买记录'} ›</button></footer></article>`).join('')}<button class="loadmore" data-act="more" ${s.more?'disabled':''}>${s.more?'已显示全部示例订单':'加载更早的订单 ↓'}</button></div>${tabs('orders')}`}
function points(){return miniHeader('选择自提点','/mini/home')+`<div class="miniscroll"><div class="miniheading"><h2>选择方便领取的地方</h2></div>${pts.map(p=>`<button class="pointoption ${s.point===p.id?'selected':''}" data-act="choose-point" data-id="${p.id}"><strong>${p.name} ${s.point===p.id?'✓':''}</strong><small>${p.address}</small><small style="margin-top:8px;color:var(--green)">${(s.selected.includes(p.id)?1:0)+(p.id==='north'?1:0)} 个可购团期 · 到货时间按各团期查看</small></button>`).join('')}<p class="samplelabel">选择不会修改已有订单的领取地点</p></div>${tabs('home')}`}
function review(){return `<main><div style="text-align:center;padding:42px 20px 0"><div class="eyebrow">DESIGN DECISIONS</div><h1>先确认经营方式，再落到产品。</h1><p class="muted" style="font-size:13px;margin-top:10px">这份原型展示候选方案，所有操作只影响浏览器内的示例。</p></div><div class="checks"><section class="panel"><h2>需要你确认的 3 件事</h2><ul><li>同一活动是否覆盖多个自提点？</li><li>各点独立成团，还是所有点合计成团？</li><li>库存是否按点分配、领取时间是否允许不同？</li></ul><div class="formsummary">当前预览：${modeText()}，门槛 ${s.threshold} 件；${selected().length} 个自提点，库存按点分配、分别领取。</div><div class="formfooter"><a href="#/admin/new"><button class="primary">切换方案对比</button></a></div></section><section class="panel"><h2>这版可以实际点击什么</h2><ul><li>后台配置活动 → 选择多个自提点</li><li>切换成团口径 → 查看各点进度变化</li><li>从点位跳转小程序 → 查看对应商品</li><li>切换点位、查看团期时间与成团规则</li><li>订单分类、加载历史、查看旧商品记录</li><li>后台订单详情、取消确认与对账差异处理</li></ul><small>路由支持浏览器前进/后退。恢复示例只重置原型数据。</small><div class="formfooter"><button data-act="reset">恢复初始示例</button></div></section></div></main>`}
function showModal(title,body,confirm='',act=''){modal={title,body,confirm,act};render()}
function render(){route=location.hash.slice(1)||'/admin/activities';let body;if(route.startsWith('/mini')){let fn={'/mini/home':miniHome,'/mini/detail':miniDetail,'/mini/orders':miniOrders,'/mini/points':points}[route]||miniHome;body=miniShell(fn())}else if(route==='/review')body=review();else body=adminShell(route==='/admin/new'?form():route==='/admin/orders/DEMO-0028'?orderDetail():route==='/admin/orders'?orders():route==='/admin/finance'?finance():activities());document.getElementById('app').innerHTML=toolbar()+body+(modal?`<div class="modalshade"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${modal.title}</h2><p>${modal.body}</p><div class="actions"><button data-act="dismiss">${modal.confirm?'暂不操作':'知道了'}</button>${modal.confirm?`<button class="primary" data-act="${modal.act}">${modal.confirm}</button>`:''}</div></section></div>`:'');const formPhoto=document.querySelector('#campaign-form .row img');if(formPhoto)Object.assign(formPhoto.style,{width:'58px',height:'58px',objectFit:'cover',borderRadius:'9px'});if(modal)document.querySelector('.dialog button').focus()}
window.addEventListener('hashchange',()=>{modal=null;render();window.scrollTo(0,0)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const b=[...document.querySelectorAll('.dialog button')];if(e.shiftKey&&document.activeElement===b[0]){e.preventDefault();b.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===b.at(-1)){e.preventDefault();b[0].focus()}}});
document.addEventListener('submit',e=>{if(e.target.id!=='campaign-form')return;e.preventDefault();const f=new FormData(e.target),chosen=f.getAll('points');if(!chosen.length){toast('请至少选择一个自提点');return}const title=String(f.get('title')).trim();if(!title){toast('请填写活动名称');return}s.title=title;s.mode=f.get('mode');s.threshold=Number(f.get('threshold'));s.selected=chosen;s.published=true;if(!chosen.includes(s.point))s.point=chosen[0];persist();go('/admin/activities');toast('已保存示例配置，可从各点进入小程序预览')});
document.addEventListener('click',e=>{const b=e.target.closest('[data-act],[data-go]');if(!b||b.disabled)return;if(b.dataset.go){go(b.dataset.go);return}const a=b.dataset.act,id=b.dataset.id;if(a==='edit')go('/admin/new');else if(a==='cancel-edit')go('/admin/activities');else if(a==='preview'){s.point=id;persist();go('/mini/home')}else if(a==='choose-point'){s.point=id;persist();go('/mini/home')}else if(a==='filter'){s.orderFilter=id;persist();render()}else if(a==='more'){s.more=true;persist();render()}else if(a==='history')go('/mini/orders');else if(a==='dismiss'){modal=null;render()}else if(a==='tofu')showModal('手作豆皮专场','北城邻里自提点 · 已支付 8 / 5 件。9月30日20:00截单，10月1日领取，与米粉团期分别安排。');else if(a==='buy')showModal('确认本团领取安排',`${current().name}<br>${current().arrival} 预计到货<br>本示例只用于确认交互，下一步将沿用现有购物车与结算流程。`);else if(a==='pickup')showModal('提货安排','农家手作豆皮 · 北城邻里自提点<br>商品已到货，请于领取期限内前往。正式产品在此展示本订单有效提货码。');else if(a==='snapshot'&&id==='XW-DEMO-0008')showModal('第06期 · 购买记录',`${photo('product-tofu-strips.jpg','购买时的豆皮图片')}<br>农家手作豆皮 × 2<br>单价 ¥9.90 · 实付 ¥19.80<br>9月16日下单，已领取。该团期已结束。`);else if(a==='snapshot')showModal('第07期 · 购买记录',`${photo('product-rice-noodles.jpg','购买时的米粉图片')}<br>乡味手作米粉 500g × 2<br>单价 ¥12.80 · 实付 ¥25.60<br>9月20日下单，9月22日已领取。该团期已结束。`);else if(a==='close-order')showModal('取消这笔未付款订单？','将核对收款状态，并关闭原支付入口。若已收款或结果未知，需先处理支付结果，不能直接取消。','确认取消','confirm-close');else if(a==='confirm-close'){modal=null;s.orderState='核对中';persist();render();setTimeout(()=>{s.orderState='已关闭';persist();render();toast('示例：未收款，支付单已关闭，订单已取消')},800)}else if(a==='bill-info')showModal('账单来源与核对范围','示例日期：2026年9月27日。<br>核对支付、退款与净额，手续费单独列示。原型未接入微信账单，也没有上传或读取真实财务数据。');else if(a==='reconcile')showModal(s.reconciled?'人工核查记录':'退款差异 · ¥10.00',s.reconciled?'示例核查结果：微信退款已成功，平台记录待同步。已登记处理结果，不修改原始账单。':'平台退款 ¥0.00，微信账单退款 ¥10.00。<br>建议先核对退款单与回调，再记录处理依据。此示例采用“退款已成功，平台记录待同步”的核查结果。',s.reconciled?'':'记录示例核查结果',s.reconciled?'':'confirm-reconcile');else if(a==='confirm-reconcile'){s.reconciled=true;persist();modal=null;render();toast('已记录示例处理结果，未修改订单金额')}else if(a==='reset'){Object.assign(s,JSON.parse(JSON.stringify(initial)));persist();render();toast('已恢复初始示例')}else if(a==='search-order'){const q=document.getElementById('order-query').value.trim().toUpperCase();document.querySelectorAll('#order-rows tr').forEach(tr=>tr.hidden=!tr.textContent.toUpperCase().includes(q));if(![...document.querySelectorAll('#order-rows tr')].some(tr=>!tr.hidden))toast('没有找到这个示例订单')}else if(a==='reset-order'){document.getElementById('order-query').value='';document.querySelectorAll('#order-rows tr').forEach(tr=>tr.hidden=false)}});
render();
